-- Generated by scripts/build-professions-migration.mjs. Do not edit by hand.
-- Profession: embedded-ai · tiers 1 · 570 cards

insert into public.professions (id, name, tagline, description, icon, accent, gradient, planned_cards, position)
values ('embedded-ai', 'Embedded AI Engineering', 'Make machine learning run on tiny, power-sipping chips.', 'From bits, volts and your first C program to the systems that run neural networks on microcontrollers, phones and custom chips: embedded systems, signal processing, deep learning, model compression, ML compilers and accelerators, up to today''s research on efficient AI. It follows the syllabi of leading university courses and the field''s standard books.', 'chip', '#0FA3A3', array['#16C2C2', '#3B82F6']::text[], 5000, 1)
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  icon = excluded.icon, accent = excluded.accent, gradient = excluded.gradient, planned_cards = excluded.planned_cards,
  position = excluded.position;

insert into public.profession_tiers (profession_id, tier, slug, name, milestone, summary, planned_cards) values
  ('embedded-ai', 0, 'foundations', 'Foundations', null, 'You can write and debug small Python and C programs, use the command line and Git, read binary and hex, and work out voltages, currents, power and battery life with the right units.', 400),
  ('embedded-ai', 1, 'core-engineering', 'Core engineering', null, 'You understand how software meets hardware: memory and pointers in C, core data structures, small analog and digital circuits, how a RISC-V processor with caches runs code, number formats, and safe multithreading. You can estimate cost, timing and power at each of these layers.', 600),
  ('embedded-ai', 2, 'embedded-systems', 'Embedded systems', 'Junior engineer', 'You can bring up, program, debug and ship firmware for a microcontroller: boot it from scratch, handle interrupts, peripherals and sensors, run tasks under an RTOS, save power and update it securely. You can also work on an embedded Linux board with an AI accelerator.', 600),
  ('embedded-ai', 3, 'math-signals', 'Math and signals for ML', null, 'You can do the math that models are built on (vectors, gradients, probabilities and bits) and turn raw sensor signals into clean features that a small model can use.', 500),
  ('embedded-ai', 4, 'ml-deep-learning', 'ML and deep learning', 'Bachelor''s', 'You can build, train and debug classic models and modern neural networks (CNNs, sequence models and transformers) in PyTorch, and explain how today''s LLMs and diffusion models are trained and run.', 650),
  ('embedded-ai', 5, 'efficient-ml-tinyml', 'Efficient ML and TinyML', 'Master''s', 'You can measure what a model costs in operations, memory, energy and time, shrink it with pruning, quantization, efficient architectures and distillation, and deploy and benchmark it on microcontrollers and edge chips.', 750),
  ('embedded-ai', 6, 'ml-systems', 'ML systems: compilers, runtimes, accelerators', null, 'You can make ML code run fast on CPUs, GPUs, NPUs and FPGAs: measure where time goes, compile and tune kernels, plan memory, and reason about how an accelerator moves data. You can split a model across a device''s processors and predict the result before deploying.', 750),
  ('embedded-ai', 7, 'phd-core', 'Advanced / PhD core', 'Quals', 'You can answer qualifying-exam questions on how processors and memory systems work and on accelerator research topics: sparsity, number formats, hardware–model co-design, on-device training, emerging hardware and security. You can evaluate a design with sound methodology and reproduce a published result.', 500),
  ('embedded-ai', 8, 'research-frontier', 'Research frontier', 'PhD', 'You can read and critique current research on compressing and running large models on devices, and you know the state of low-bit formats, edge chips and benchmarks as of late 2026. You can tell which open problems remain and judge vendor claims against first principles.', 250)
on conflict (profession_id, tier) do update set slug = excluded.slug, name = excluded.name, milestone = excluded.milestone,
  summary = excluded.summary, planned_cards = excluded.planned_cards;

insert into public.profession_modules (id, profession_id, tier, position, title, summary, planned_cards, refs, practice) values
  ('embedded-ai/digital-representation', 'embedded-ai', 0, 0, 'Digital representation', 'Read and convert the binary and hex numbers, byte sizes and text codes that computers use.', 50, array['CS50x 2026, Week 0 (Scratch) and Week 4 (Memory) lectures', 'Bryant & O''Hallaron, CS:APP 3e, ch. 2 (Representing and Manipulating Information)', 'Harris & Harris, Digital Design and Computer Architecture RISC-V ed., ch. 1 (From Zero to One)']::text[], '[]'::jsonb),
  ('embedded-ai/engineering-numeracy', 'embedded-ai', 0, 1, 'Engineering numeracy', 'Do the everyday maths of engineering: powers, logarithms, unit prefixes, unit checks and graphs.', 50, array['OpenStax College Algebra 2e, ch. 1 (Prerequisites), ch. 3–4 (Functions; Linear Functions) and ch. 6 (Exponential and Logarithmic Functions)', 'OpenStax University Physics Vol. 1, ch. 1 (Units and Measurement)']::text[], '[]'::jsonb),
  ('embedded-ai/electricity-basics', 'embedded-ai', 0, 2, 'Electricity basics', 'Calculate voltage, current, resistance, power and battery life for simple circuits.', 55, array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2 (Theory), ch. 3 (Basic Electronic Components), ch. 7 (Hands-on Electronics)', 'OpenStax University Physics Vol. 2, §9.4–9.5 and §10.2–10.4']::text[], '[{"title":"PhET Circuit Construction Kit: DC (build series and parallel circuits and check Ohm''s law)","url":"https://phet.colorado.edu/en/simulations/circuit-construction-kit-dc"}]'::jsonb),
  ('embedded-ai/python-1', 'embedded-ai', 0, 3, 'Python I', 'Write small Python programs that make decisions, repeat work, use functions and handle files and errors.', 70, array['CS50P (Harvard), Lectures 0–6 and 9', 'CS50x 2026, Week 6 (Python)', 'The Python Tutorial (docs.python.org), ch. 3–8 and 15']::text[], '[{"title":"CS50P problem sets 0–6","url":"https://cs50.harvard.edu/python/psets/"}]'::jsonb),
  ('embedded-ai/python-2-numpy', 'embedded-ai', 0, 4, 'Python II and NumPy', 'Build your own Python classes and crunch arrays of numbers quickly with NumPy, then plot the results.', 55, array['CS50P, Lecture 8 (Object-Oriented Programming)', 'NumPy User Guide: the absolute basics for beginners; NumPy fundamentals', 'Dive into Deep Learning (d2l.ai), ch. 2 (Preliminaries)', 'Matplotlib documentation: Quick start guide']::text[], '[{"title":"NumPy: the absolute basics for beginners (work through every example)","url":"https://numpy.org/doc/stable/user/absolute_beginners.html"},{"title":"NumPy tutorials (start with the Moore''s Law application: fit and plot real data)","url":"https://numpy.org/numpy-tutorials/"}]'::jsonb),
  ('embedded-ai/developer-tooling', 'embedded-ai', 0, 5, 'Developer tooling', 'Work confidently in a terminal, manage Python environments, track code with Git and read error messages.', 45, array['MIT Missing Semester 2026: Introduction to the Shell; Command-line Environment; Debugging and Profiling; Version Control and Git; Packaging and Shipping Code', 'Pro Git 2e (git-scm.com), ch. 2 (Git Basics) and ch. 3 (Git Branching)', 'The Python Tutorial, ch. 12 (Virtual Environments and Packages)']::text[], '[{"title":"Missing Semester 2026: shell lecture exercises","url":"https://missing.csail.mit.edu/2026/course-shell/"},{"title":"Learn Git Branching (interactive branching, merging and rebasing levels)","url":"https://learngitbranching.js.org/"}]'::jsonb),
  ('embedded-ai/c-1', 'embedded-ai', 0, 6, 'C I', 'Write, compile and debug small C programs that use integers, functions, arrays and strings.', 75, array['Kernighan & Ritchie, The C Programming Language 2e, ch. 1–4', 'CS50x 2026, Week 1 (C) and Week 2 (Arrays)', 'Bryant & O''Hallaron, CS:APP 3e, ch. 7 (Linking)']::text[], '[{"title":"CS50x Problem Set 1 (Mario, Cash or Credit)","url":"https://cs50.harvard.edu/x/psets/1/"},{"title":"CS50x problem sets index (continue with Problem Set 2)","url":"https://cs50.harvard.edu/x/psets/"}]'::jsonb),
  ('embedded-ai/c-2-memory', 'embedded-ai', 1, 7, 'C II: memory', 'Control memory directly in C with pointers, structs, dynamic allocation and bit masks, and avoid undefined behaviour.', 90, array['Kernighan & Ritchie 2e, ch. 5 (Pointers and Arrays) and ch. 6 (Structures)', 'Bryant & O''Hallaron, CS:APP 3e, ch. 3 (§3.7–3.9) and ch. 9 (§9.9, §9.11)', 'CS50x 2026, Week 4 (Memory)']::text[], '[{"title":"CS50x Problem Set 4 (Volume, Filter, Recover)","url":"https://cs50.harvard.edu/x/psets/4/"}]'::jsonb),
  ('embedded-ai/data-structures-algorithms', 'embedded-ai', 1, 8, 'Data structures and algorithms', 'Pick and build the right data structure and algorithm, and estimate how its cost grows with input size.', 80, array['Cormen, Leiserson, Rivest & Stein, Introduction to Algorithms (CLRS) 4e, ch. 2–3, 6–8, 10–13, 16, 20', 'CS50x 2026, Week 3 (Algorithms) and Week 5 (Data Structures)']::text[], '[{"title":"CS50x Speller: build a fast hash-table spell checker in C","url":"https://cs50.harvard.edu/x/psets/5/speller/"}]'::jsonb),
  ('embedded-ai/modern-cpp-embedded', 'embedded-ai', 1, 9, 'Modern C++ for embedded', 'Use modern C++ features safely on small devices that have no heap and no exceptions.', 60, array['Stroustrup, A Tour of C++ 3e, ch. 1–8, 10, 12–13, 15–16', 'Embedded Template Library (etlcpp.com) documentation']::text[], '[{"title":"Compiler Explorer: compare the assembly generated for C and C++ versions of the same code","url":"https://godbolt.org/"}]'::jsonb),
  ('embedded-ai/circuits-analog', 'embedded-ai', 1, 10, 'Circuits and analog', 'Analyse and design the small analog circuits around a microcontroller: dividers, RC filters, transistor switches, op-amps and power supplies.', 65, array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2–5, 8, 9, 11', 'OpenStax University Physics Vol. 2, ch. 10 (Direct-Current Circuits)']::text[], '[{"title":"Falstad Circuit Simulator: build dividers, RC filters, MOSFET switches and op-amp stages","url":"https://www.falstad.com/circuit/"}]'::jsonb),
  ('embedded-ai/digital-logic', 'embedded-ai', 1, 11, 'Digital logic', 'Design logic circuits, from gates and adders to clocked state machines, and reason about their timing and power.', 70, array['Harris & Harris, Digital Design and Computer Architecture RISC-V ed., ch. 1–3 and 5', 'MIT 6.191 Computation Structures (Fall 2026), L01–L09 and Labs 1–3']::text[], '[{"title":"Nand2Tetris Projects 1–3: build gates, an ALU and memory from NAND","url":"https://www.nand2tetris.org/course"}]'::jsonb),
  ('embedded-ai/computer-organization', 'embedded-ai', 1, 12, 'Computer organization', 'Explain how a processor runs RISC-V programs and how pipelines, caches and virtual memory set its performance.', 90, array['Harris & Harris, DDCA RISC-V ed., ch. 6 (Architecture), ch. 7 (Microarchitecture), ch. 8 (Memory Systems)', 'Patterson & Hennessy, Computer Organization and Design RISC-V ed., ch. 1, 2, 4, 5', 'MIT 6.191 (Fall 2026), L10–L19 and Labs 4–7', 'Bryant & O''Hallaron, CS:APP 3e, ch. 6 (The Memory Hierarchy)']::text[], '[{"title":"RARS: write and single-step RISC-V assembly programs","url":"https://github.com/TheThirdOne/rars"},{"title":"Nand2Tetris Projects 4–6: machine language, a CPU and an assembler","url":"https://www.nand2tetris.org/course"}]'::jsonb),
  ('embedded-ai/number-formats', 'embedded-ai', 1, 13, 'Number formats', 'Choose and use fixed-point and floating-point formats, and control rounding, overflow and accumulator size.', 55, array['Goldberg 1991, ''What Every Computer Scientist Should Know About Floating-Point Arithmetic'' (ACM Computing Surveys)', 'Harris & Harris, DDCA RISC-V ed., ch. 5 (Digital Building Blocks: number systems)', 'Bryant & O''Hallaron, CS:APP 3e, §2.4 Floating Point', 'White, Making Embedded Systems 2e, ch. 12 (Math)']::text[], '[{"title":"Float Toy: flip the bits of half, single and double precision floats","url":"https://evanw.github.io/float-toy/"}]'::jsonb),
  ('embedded-ai/operating-systems', 'embedded-ai', 1, 14, 'Operating systems', 'Explain how an operating system shares the CPU and talks to devices, and write correct multithreaded code with locks.', 60, array['Arpaci-Dusseau & Arpaci-Dusseau, Operating Systems: Three Easy Pieces (OSTEP), ch. 4–8, 26–33, 36', 'Bryant & O''Hallaron, CS:APP 3e, §8.1 and §12.3–12.5', 'MIT 6.191 (Fall 2026), L16 OS; L19 Exceptions, I/O; L20 Synchronization']::text[], '[{"title":"OSTEP homework simulators (scheduling, threads and locks)","url":"https://github.com/remzi-arpacidusseau/ostep-homework"},{"title":"OSTEP projects (start with the concurrency projects)","url":"https://github.com/remzi-arpacidusseau/ostep-projects"}]'::jsonb),
  ('embedded-ai/hdl-fpga-basics', 'embedded-ai', 1, 15, 'HDL and FPGA basics', 'Describe simple hardware in SystemVerilog, test it in simulation and map it onto an FPGA.', 30, array['Harris & Harris, DDCA RISC-V ed., ch. 4 (Hardware Description Languages)', 'Harris & Harris, DDCA RISC-V ed., ch. 5 (Digital Building Blocks: logic arrays) and Appendix A (Digital System Implementation)', 'Arm Education, Introduction to Very Large-Scale Integration Design (HDL/RTL and EDA tools)']::text[], '[{"title":"HDLBits: Verilog practice problems with simulation feedback","url":"https://hdlbits.01xz.net/"}]'::jsonb),
  ('embedded-ai/mcu-architecture', 'embedded-ai', 2, 16, 'MCU architecture', 'Choose a microcontroller and find your way around its cores, memory map, buses and clocks using its datasheets.', 75, array['Yiu, The Definitive Guide to ARM Cortex-M3 and Cortex-M4 Processors 3e, ch. 1–6 and 9', 'Yiu, Definitive Guide to Arm Cortex-M23 and Cortex-M33 Processors, ch. 1 and 3', 'Valvano, Embedded Systems: Introduction to ARM Cortex-M Microcontrollers (Vol. 1), ch. 3', 'Valvano, Embedded Systems: Real-Time Operating Systems for ARM Cortex-M Microcontrollers (Vol. 3), ch. 1', 'White, Making Embedded Systems 2e, ch. 3']::text[], '[]'::jsonb),
  ('embedded-ai/bare-metal-toolchain', 'embedded-ai', 2, 17, 'Bare-metal and toolchain', 'Build, link and boot firmware from scratch, and drive pins by writing hardware registers.', 75, array['White, Making Embedded Systems 2e, ch. 2–4', 'Valvano, Vol. 1, ch. 4 (Introduction to Input/Output) and ch. 5 (Modular Programming)', 'Yiu, Cortex-M3/M4 3e, ch. 2 (Introduction to Embedded Software Development)', 'GNU ld manual, ch. 3 (Linker Scripts)', 'Bryant & O''Hallaron, CS:APP 3e, ch. 7 (Linking)']::text[], '[{"title":"Bare-metal programming guide: from an empty folder to blinky, SysTick and UART without a vendor framework","url":"https://github.com/cpq/bare-metal-programming-guide"},{"title":"CMake Tutorial (steps 1–4), then add a cross-compilation toolchain file","url":"https://cmake.org/cmake/help/latest/guide/tutorial/index.html"}]'::jsonb),
  ('embedded-ai/interrupts-timers-dma', 'embedded-ai', 2, 18, 'Interrupts, timers, DMA', 'Make firmware react to events on time using interrupts, timers, PWM and DMA.', 65, array['Yiu, Cortex-M3/M4 3e, ch. 7 (Exceptions and Interrupts), ch. 8 (Exception Handling in Detail) and §9.5 (The SysTick timer)', 'White, Making Embedded Systems 2e, ch. 4 (Outputs, Inputs, and Timers) and ch. 5 (Interrupts)', 'Valvano, Vol. 1, ch. 9 (Interrupt Programming and Real-time Systems)', 'Valvano, Vol. 3, ch. 7 (High-Speed Interfacing)']::text[], '[{"title":"Zephyr PWM Blinky sample: drive an LED with hardware PWM","url":"https://docs.zephyrproject.org/latest/samples/basic/blinky_pwm/README.html"}]'::jsonb),
  ('embedded-ai/peripherals-connectivity', 'embedded-ai', 2, 19, 'Peripherals and connectivity', 'Talk to sensors, chips and other devices over UART, SPI, I2C, I2S, CAN, USB and wireless links.', 65, array['White, Making Embedded Systems 2e, ch. 7 (Communicating with Peripherals), ch. 8 (Putting Together a System), ch. 10 (Building Connected Devices)', 'Valvano, Vol. 1, ch. 8 (Serial and Parallel Port Interfacing) and ch. 11 (Communication Systems)', 'Arm Education, Embedded Systems Essentials with Arm: Get Practical with Hardware (serial communication modules)', 'Arm Education, Build Your First IoT Application on Arm (connectivity modules)']::text[], '[{"title":"Zephyr UART echo sample: interrupt-driven UART receive","url":"https://docs.zephyrproject.org/latest/samples/drivers/uart/echo_bot/README.html"},{"title":"Zephyr Heart-rate Monitor (Peripheral) sample: a BLE GATT peripheral","url":"https://docs.zephyrproject.org/latest/samples/bluetooth/peripheral_hr/README.html"}]'::jsonb),
  ('embedded-ai/sensors-acquisition', 'embedded-ai', 2, 20, 'Sensors and acquisition', 'Turn real-world signals from ADCs, IMUs, microphones and cameras into clean, correctly sampled data.', 60, array['Lee & Seshia, Introduction to Embedded Systems 2e, ch. 7 (Sensors and Actuators)', 'White, Making Embedded Systems 2e, ch. 8 (Putting Together a System)', 'Valvano, Real-Time Interfacing ebook (ECE445L), ch. 2 (Digital Sampling) and ch. 5 (Audio)', 'Scherz & Monk 4e, ch. 6 (Sensors)']::text[], '[{"title":"Zephyr ADC with devicetree sample: read channels and convert to millivolts","url":"https://docs.zephyrproject.org/latest/samples/drivers/adc/adc_dt/README.html"}]'::jsonb),
  ('embedded-ai/rtos', 'embedded-ai', 2, 21, 'RTOS', 'Structure firmware as prioritised tasks with FreeRTOS or Zephyr and check that every deadline is met.', 90, array['FreeRTOS Kernel Book (github.com/FreeRTOS/FreeRTOS-Kernel-Book), ch. 1–13', 'Zephyr Project documentation: Kernel Services; Devicetree guide; Configuration System (Kconfig)', 'Valvano, Vol. 3 (Real-Time Operating Systems for ARM Cortex-M), ch. 3–5', 'Lee & Seshia 2e, ch. 12 (Scheduling)', 'Yiu, Cortex-M3/M4 3e, ch. 10 (OS Support Features)']::text[], '[{"title":"RTOS sensor project (capstone), step 1: install Zephyr and build Blinky for your board","url":"https://docs.zephyrproject.org/latest/develop/getting_started/index.html"},{"title":"RTOS sensor project, step 2: read an MPU6050 IMU over I2C (start from this sample and add a devicetree overlay for your board)","url":"https://docs.zephyrproject.org/latest/samples/sensor/mpu6050/README.html"},{"title":"RTOS sensor project, step 3: stream samples over UART with interrupt-driven I/O (adapt the UART echo sample)","url":"https://docs.zephyrproject.org/latest/samples/drivers/uart/echo_bot/README.html"},{"title":"RTOS sensor project, step 4: split acquisition, processing and output into threads that hand off with semaphores and queues (see Basic Synchronization)","url":"https://docs.zephyrproject.org/latest/samples/synchronization/README.html"},{"title":"RTOS sensor project, FreeRTOS variant: build the same pipeline starting from the FreeRTOS Kernel Quick Start Guide","url":"https://www.freertos.org/Documentation/01-FreeRTOS-quick-start/01-Beginners-guide/02-Quick-start-guide"},{"title":"FreeRTOS Kernel Book and its examples (tasks, queues, mutexes, interrupts)","url":"https://github.com/FreeRTOS/FreeRTOS-Kernel-Book"}]'::jsonb),
  ('embedded-ai/embedded-linux-edge-socs', 'embedded-ai', 2, 22, 'Embedded Linux and edge SoCs', 'Bring up and develop on Linux-based edge computers such as Raspberry Pi and Jetson, and understand their AI accelerators.', 60, array['Simmonds & Vasquez, Mastering Embedded Linux Programming 3e, ch. 3–7, 11, 13, 19', 'mlsysbook.ai, Machine Learning Systems Vol. I, ch. 2 (System Paradigms) and ch. 11 (Hardware Acceleration)', 'Buildroot user manual; Yocto Project Quick Build']::text[], '[{"title":"Buildroot quick start: build a minimal image for QEMU or a Raspberry Pi defconfig","url":"https://buildroot.org/downloads/manual/manual.html"},{"title":"Yocto Project Quick Build: build an image and boot it in QEMU","url":"https://docs.yoctoproject.org/brief-yoctoprojectqs/index.html"}]'::jsonb),
  ('embedded-ai/low-power-design', 'embedded-ai', 2, 23, 'Low-power design', 'Make a battery-powered device last by budgeting, reducing and measuring its power use.', 60, array['White, Making Embedded Systems 2e, ch. 13 (Reducing Power Consumption)', 'Warden & Situnayake, TinyML, ch. 15 (Optimizing Latency) and ch. 16 (Optimizing Energy Usage)', 'Yiu, Cortex-M3/M4 3e, ch. 9 (Low Power and System Control Features)', 'FreeRTOS Kernel Book, ch. 11 (Low Power Support)']::text[], '[]'::jsonb),
  ('embedded-ai/debug-test-secure-firmware', 'embedded-ai', 2, 24, 'Debug, test, secure firmware', 'Find bugs on real hardware, test firmware automatically, and ship updates that boot securely.', 50, array['White, Making Embedded Systems 2e, ch. 9 (Getting Into Trouble) and ch. 10 (Building Connected Devices)', 'Yiu, Cortex-M3/M4 3e, ch. 11 (Memory Protection Unit) and ch. 12 (Fault Exceptions and Fault Handling)', 'Yiu, Definitive Guide to Arm Cortex-M23 and Cortex-M33 Processors, ch. 7, 16, 18, 22', 'MIT Missing Semester 2026: Debugging and Profiling; Code Quality']::text[], '[{"title":"Unity: unit-test a ring buffer or a sensor-conversion module on your PC","url":"https://github.com/ThrowTheSwitch/Unity"},{"title":"MCUboot documentation: sign an image and run a test upgrade","url":"https://docs.mcuboot.com/"}]'::jsonb),
  ('embedded-ai/linear-algebra', 'embedded-ai', 3, 25, 'Linear algebra', 'Work with vectors, matrices and tensors: multiply them, count what that costs, and compress a matrix with the SVD.', 110, array['Strang, Introduction to Linear Algebra (6th ed., 2023), ch. 1–4, 6–7', 'Deisenroth, Faisal & Ong, Mathematics for Machine Learning (MML, 2020), ch. 2–4', 'Zhang et al., Dive into Deep Learning (D2L), §2.1 and §2.3']::text[], '[]'::jsonb),
  ('embedded-ai/calculus-optimization', 'embedded-ai', 3, 26, 'Calculus and optimization', 'Take derivatives of the functions inside a model, follow the gradient downhill, and know when that search is guaranteed to work.', 95, array['MML, ch. 5 (Vector Calculus) and ch. 7 (Continuous Optimization)', 'D2L, §2.4–2.5, §22.3–22.4 and ch. 12']::text[], '[{"title":"micrograd: build a tiny reverse-mode autodiff engine","url":"https://github.com/karpathy/micrograd"}]'::jsonb),
  ('embedded-ai/probability-statistics', 'embedded-ai', 3, 27, 'Probability and statistics', 'Reason about uncertainty: compute probabilities, use Bayes'' rule, fit parameters to data, and put error bars on a measured accuracy.', 90, array['Blitzstein & Hwang, Introduction to Probability (2nd ed., 2019), ch. 1–10', 'MML, ch. 6 and §8.3', 'D2L, §2.6 and §22.6–22.10']::text[], '[]'::jsonb),
  ('embedded-ai/information-theory', 'embedded-ai', 3, 28, 'Information theory', 'Measure information in bits, see why cross-entropy is the standard loss, and estimate how few bits a model''s weights really need.', 40, array['MacKay, Information Theory, Inference, and Learning Algorithms (2003), ch. 1–2, 4–6', 'D2L, §22.11']::text[], '[]'::jsonb),
  ('embedded-ai/signals-dsp', 'embedded-ai', 3, 29, 'Signals and DSP', 'Turn sensor readings into clean digital signals: sample without aliasing, convolve, filter, and see a signal''s frequencies with the FFT.', 85, array['Smith, The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 3, 5–12, 14–21', 'Oppenheim & Willsky, Signals and Systems (2nd ed., 1997), ch. 1–7, 10']::text[], '[]'::jsonb),
  ('embedded-ai/sensor-feature-extraction', 'embedded-ai', 3, 30, 'Sensor feature extraction', 'Turn raw audio, images and motion data into the small feature arrays that tiny models expect, one window at a time.', 50, array['Warden & Situnayake, TinyML (O''Reilly, 2019), ch. 7–12', 'Edge Impulse docs: processing blocks (spectrogram, MFE, MFCC, image, spectral analysis)', 'Smith, DSP Guide, ch. 22']::text[], '[{"title":"Edge Impulse: end-to-end motion recognition with spectral features","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/motion-recognition"}]'::jsonb),
  ('embedded-ai/numerical-computing', 'embedded-ai', 3, 31, 'Numerical computing', 'Keep results accurate in finite precision and see how convolutions are turned into fast matrix multiplies.', 30, array['Goldberg, What Every Computer Scientist Should Know About Floating-Point Arithmetic (ACM Computing Surveys, 1991)', 'Goodfellow, Bengio & Courville, Deep Learning (2016), ch. 4', 'Sze, Chen, Yang & Emer, Efficient Processing of Deep Neural Networks: A Tutorial and Survey (Proc. IEEE, 2017)', 'Lavin & Gray, Fast Algorithms for Convolutional Neural Networks (CVPR 2016)']::text[], '[]'::jsonb),
  ('embedded-ai/ml-fundamentals', 'embedded-ai', 4, 32, 'ML fundamentals', 'Frame a learning problem, split the data honestly, fit simple linear models, and judge a classifier with the right metric.', 80, array['Géron, Hands-On Machine Learning with Scikit-Learn, Keras & TensorFlow (3rd ed., 2022), ch. 1–4', 'Prince, Understanding Deep Learning (UDL, MIT Press 2023), ch. 1–2, 8–9', 'D2L, ch. 3–4']::text[], '[]'::jsonb),
  ('embedded-ai/classical-ml-on-devices', 'embedded-ai', 4, 33, 'Classical ML on devices', 'Use small classic models (nearest neighbors, trees, SVMs, k-means and PCA) that often fit a microcontroller''s budget better than a neural network.', 50, array['Géron (3rd ed.), ch. 5–9', 'MML, ch. 10–12', 'Edge Impulse docs: K-means and GMM anomaly-detection blocks']::text[], '[]'::jsonb),
  ('embedded-ai/neural-network-basics', 'embedded-ai', 4, 34, 'Neural-network basics', 'Build a neural network from layers and activations, pick a loss, and compute every gradient with backpropagation.', 80, array['UDL, ch. 3–7', 'D2L, ch. 5', 'Stanford CS231n course notes: Backpropagation; Neural Networks Parts 1–3']::text[], '[{"title":"micrograd: an autograd engine and small MLP built from scratch","url":"https://github.com/karpathy/micrograd"},{"title":"Stanford CS231n notes: minimal neural network case study","url":"https://cs231n.github.io/"}]'::jsonb),
  ('embedded-ai/training-deep-networks', 'embedded-ai', 4, 35, 'Training deep networks', 'Train deep networks reliably: choose an optimizer and learning-rate schedule, normalize and regularize, use mixed precision, and debug runs that fail.', 75, array['D2L, ch. 12, §5.6, §8.5 and §14.1', 'UDL, ch. 6, 9 and 11', 'Micikevicius et al., Mixed Precision Training (ICLR 2018)']::text[], '[]'::jsonb),
  ('embedded-ai/pytorch-in-practice', 'embedded-ai', 4, 36, 'PyTorch in practice', 'Write real PyTorch (tensors, autograd, modules and a training loop) and export the trained model for deployment.', 70, array['PyTorch tutorials: Learn the Basics', 'PyTorch docs: Autograd mechanics; torch.export; torch.onnx; Automatic Mixed Precision', 'LiteRT docs: post-training quantization', 'Géron (3rd ed.), ch. 10']::text[], '[{"title":"PyTorch tutorial: Learn the Basics (tensors to a full training loop)","url":"https://docs.pytorch.org/tutorials/beginner/basics/intro.html"}]'::jsonb),
  ('embedded-ai/cnns-vision', 'embedded-ai', 4, 37, 'CNNs and vision', 'Build convolutional networks for images, count their parameters and operations, and use the efficient blocks and detectors that run on edge devices.', 90, array['Stanford CS231n course notes: Convolutional Neural Networks; Transfer Learning', 'D2L, ch. 7–8 and §14.1–14.8', 'UDL, ch. 10–11']::text[], '[{"title":"MLPerf Tiny reference training code (image classification on CIFAR-10)","url":"https://github.com/mlcommons/tiny/tree/master/benchmark"}]'::jsonb),
  ('embedded-ai/sequence-audio-models', 'embedded-ai', 4, 38, 'Sequence and audio models', 'Model signals that unfold over time and build the small keyword-spotting networks that listen continuously on microcontrollers.', 40, array['D2L, ch. 9–10', 'Warden & Situnayake, TinyML, ch. 7–8', 'mlsysbook.ai Vol. I, §6.5']::text[], '[{"title":"MLPerf Tiny keyword-spotting reference training (DS-CNN on Speech Commands)","url":"https://github.com/mlcommons/tiny/tree/master/benchmark/training/keyword_spotting"}]'::jsonb),
  ('embedded-ai/transformers', 'embedded-ai', 4, 39, 'Transformers', 'Understand attention and the transformer block, and work out what a transformer costs in operations and memory, including the KV cache.', 90, array['UDL, ch. 12', 'Stanford CS224n (Winter 2026), lectures ''Transformers'' and ''Pretraining''', 'D2L, ch. 11', 'Vaswani et al., Attention Is All You Need (NeurIPS 2017)']::text[], '[{"title":"The Annotated Transformer (line-by-line implementation)","url":"https://nlp.seas.harvard.edu/annotated-transformer/"},{"title":"nanoGPT: train and fine-tune a small GPT","url":"https://github.com/karpathy/nanoGPT"}]'::jsonb),
  ('embedded-ai/generative-ai-llms', 'embedded-ai', 4, 40, 'Generative AI and LLMs', 'Follow how a large language model is built (tokens, pretraining, scaling, fine-tuning and preference tuning), how it generates text, and how diffusion models generate images.', 75, array['Raschka, Build a Large Language Model (From Scratch) (Manning, 2024), ch. 1–7 and App. E', 'UDL, ch. 12, 15, 17–18', 'Stanford CS224n (Winter 2026), lectures ''Pretraining (Scaling, Systems, Data)'' and ''Post-training (RLHF, SFT, DPO)''']::text[], '[{"title":"Raschka, LLMs-from-scratch: build, pretrain and fine-tune a GPT","url":"https://github.com/rasbt/LLMs-from-scratch"}]'::jsonb),
  ('embedded-ai/efficiency-metrics', 'embedded-ai', 5, 41, 'Efficiency metrics', 'Measure what a model costs in operations, memory, energy and time, and use a simple roofline to see what limits its speed.', 85, array['MIT 6.5940 (Fall 2024) Lectures 1–2: Introduction; Basics of Deep Learning', 'Sze, Chen, Yang & Emer, Efficient Processing of Deep Neural Networks: A Tutorial and Survey (Proc. IEEE, 2017)', 'Horowitz, Computing''s Energy Problem (and What We Can Do About It) (ISSCC 2014)', 'Williams, Waterman & Patterson, Roofline: An Insightful Visual Performance Model for Multicore Architectures (CACM, 2009)', 'mlsysbook.ai Vol. I, ch. 11 (§11.5–11.7)']::text[], '[]'::jsonb),
  ('embedded-ai/tinyml-workflow', 'embedded-ai', 5, 42, 'TinyML workflow and applications', 'Take a TinyML idea from data to a working device for keyword spotting, person detection, gestures and anomaly detection, using the Edge Impulse workflow.', 70, array['Warden & Situnayake, TinyML (O''Reilly, 2019), ch. 1, 7–12 and 14', 'HarvardX TinyML Professional Certificate (Fundamentals, Applications and Deploying TinyML; courseware at github.com/tinyMLx/courseware)', 'Edge Impulse docs: impulse design, EON Tuner, EON Compiler']::text[], '[{"title":"Edge Impulse tutorial: keyword spotting (collect, train, deploy)","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/keyword-spotting"},{"title":"Edge Impulse tutorial: motion (gesture) recognition","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/motion-recognition"},{"title":"HarvardX TinyML Colab notebooks","url":"https://github.com/tinyMLx/colabs"}]'::jsonb),
  ('embedded-ai/pruning-sparsity', 'embedded-ai', 5, 43, 'Pruning and sparsity', 'Remove the weights and channels a network does not need, and know which kinds of sparsity actually make it smaller or faster on real hardware.', 85, array['MIT 6.5940 (Fall 2024 and Fall 2026) Lectures 3–4: Pruning and Sparsity', 'Han et al., Learning both Weights and Connections for Efficient Neural Networks (NIPS 2015)', 'Han, Mao & Dally, Deep Compression (ICLR 2016)', 'mlsysbook.ai Vol. I, §10.2.1 and §10.4.2']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 1: Pruning (Colab)","url":"https://colab.research.google.com/drive/1Fagq3JQBzCizodyxpHKvWDzfCC7F1RWN"},{"title":"PyTorch tutorial: pruning with torch.nn.utils.prune","url":"https://docs.pytorch.org/tutorials/intermediate/pruning_tutorial.html"}]'::jsonb),
  ('embedded-ai/quantization-1', 'embedded-ai', 5, 44, 'Quantization I', 'Store and compute with 8-bit integers instead of 32-bit floats: the scale and zero-point math, calibration, and integer-only kernels.', 100, array['Jacob et al., Quantization and Training of Neural Networks for Efficient Integer-Arithmetic-Only Inference (CVPR 2018)', 'Nagel et al., A White Paper on Neural Network Quantization (arXiv 2106.08295, 2021)', 'MIT 6.5940 Lecture 5: Quantization (Part I)', 'LiteRT docs: quantization specification; post-training quantization']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 2: Quantization (Colab)","url":"https://colab.research.google.com/drive/11IBla1q1McoZ2oCANCGHns8VtzG5nCMP"}]'::jsonb),
  ('embedded-ai/quantization-2', 'embedded-ai', 5, 45, 'Quantization II', 'Go below 8 bits and train for it: quantization-aware training, mixed precision, 4-bit and binary weights, FP8, and quantizing LLMs.', 70, array['MIT 6.5940 Lecture 6: Quantization (Part II), and Fall 2024 Lecture 13: Efficient LLM Deployment', 'Nagel et al. (2021), §4', 'Micikevicius et al., FP8 Formats for Deep Learning (arXiv 2209.05433, 2022)']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 4: LLM compression (Colab)","url":"https://colab.research.google.com/drive/16H9RvSg4XIF35X3fLGQUVwAE9ccvDj14"},{"title":"TensorFlow Model Optimization guide: quantization-aware training","url":"https://www.tensorflow.org/model_optimization/guide/quantization/training"}]'::jsonb),
  ('embedded-ai/efficient-architectures-nas', 'embedded-ai', 5, 46, 'Efficient architectures and NAS', 'Design networks that are efficient by construction, and let a search find the best architecture for a given device''s latency and memory.', 80, array['MIT 6.5940 Lectures 7–8: Neural Architecture Search (Parts I–II), and Lecture 10: MCUNet', 'Howard et al., MobileNets (arXiv 1704.04861, 2017); Sandler et al., MobileNetV2 (CVPR 2018)', 'Tan & Le, EfficientNet (ICML 2019)', 'Cai et al., Once-for-All (ICLR 2020)', 'Lin et al., MCUNet: Tiny Deep Learning on IoT Devices (NeurIPS 2020)', 'mlsysbook.ai Vol. I, §10.2.4–10.2.5']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 3: Neural architecture search (Colab)","url":"https://colab.research.google.com/drive/1xKReLBHVS6bkFbYkfi-Ky3C4loQmG6Yc"},{"title":"Once-for-All: pretrained supernets and specialization code","url":"https://github.com/mit-han-lab/once-for-all"}]'::jsonb),
  ('embedded-ai/distillation-low-rank', 'embedded-ai', 5, 47, 'Distillation and low-rank', 'Train a small student network to imitate a large teacher, and split big weight matrices into smaller low-rank pieces.', 40, array['MIT 6.5940 Lecture 9: Knowledge Distillation', 'Hinton, Vinyals & Dean, Distilling the Knowledge in a Neural Network (arXiv 1503.02531, 2015)', 'mlsysbook.ai Vol. I, §10.2.2–10.2.3', 'Hu et al., LoRA: Low-Rank Adaptation of Large Language Models (ICLR 2022)']::text[], '[]'::jsonb),
  ('embedded-ai/mcu-inference-engines', 'embedded-ai', 5, 48, 'MCU inference engines', 'Run quantized models on microcontrollers: how LiteRT for Microcontrollers manages memory, how optimized kernels and code generators speed it up, and how to fit models into tiny SRAM.', 110, array['MIT 6.5940 Lectures 10–11: MCUNet; TinyEngine and Parallel Processing', 'David et al., TensorFlow Lite Micro: Embedded Machine Learning on TinyML Systems (MLSys 2021)', 'LiteRT for Microcontrollers docs: overview; get started', 'CMSIS-NN (GitHub: ARM-software/CMSIS-NN)', 'Lin et al., MCUNetV2: Memory-Efficient Patch-based Inference for Tiny Deep Learning (NeurIPS 2021)', 'Arm Ethos-U Vela compiler (PyPI: ethos-u-vela)']::text[], '[{"title":"Capstone: keyword spotting on a Cortex-M board, starting from the TFLM micro_speech example","url":"https://github.com/tensorflow/tflite-micro/tree/main/tensorflow/lite/micro/examples/micro_speech"},{"title":"Capstone hardware path: micro_speech on the Arduino Nano 33 BLE Sense (Cortex-M4F)","url":"https://github.com/tensorflow/tflite-micro-arduino-examples/tree/main/examples/micro_speech"},{"title":"Capstone alternative: Edge Impulse keyword-spotting tutorial (deploy to a Cortex-M board)","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/keyword-spotting"},{"title":"TinyEngine: MIT''s memory-efficient MCU inference library","url":"https://github.com/mit-han-lab/tinyengine"}]'::jsonb),
  ('embedded-ai/edge-soc-deployment', 'embedded-ai', 5, 49, 'Phone and edge-SoC deployment', 'Deploy models on phones and edge boards through the main runtimes, sending each part of the model to the CPU, GPU or NPU that can run it.', 70, array['ExecuTorch docs: How ExecuTorch works; Backends overview; .pte file format', 'LiteRT docs: overview; delegates', 'ONNX Runtime docs: execution providers; quantization', 'coremltools docs: converting PyTorch models', 'NVIDIA TensorRT docs: quick start guide', 'mlsysbook.ai Vol. I, §11.10 and §13.7–13.8']::text[], '[{"title":"ExecuTorch: getting started (export to .pte and run)","url":"https://docs.pytorch.org/executorch/stable/getting-started.html"}]'::jsonb),
  ('embedded-ai/benchmarking', 'embedded-ai', 5, 50, 'Benchmarking', 'Measure accuracy, latency and energy the way MLPerf does, and report results that others can trust and reproduce.', 40, array['Banbury et al., MLPerf Tiny Benchmark (arXiv 2106.07597, 2021)', 'mlsysbook.ai Vol. I, ch. 12 (Benchmarking)', 'MLCommons Inference rules: scenarios (github.com/mlcommons/inference_policies)']::text[], '[{"title":"MLPerf Tiny benchmark repository (reference models, training and runner)","url":"https://github.com/mlcommons/tiny"}]'::jsonb),
  ('embedded-ai/cpu-performance', 'embedded-ai', 6, 51, 'CPU performance engineering', 'You will be able to find where a program spends its time on a CPU and speed up ML kernels with vector instructions, cache-friendly loops and a well-structured matrix multiply.', 85, array['Hennessy, Patterson & Kozyrakis, Computer Architecture: A Quantitative Approach, 7th ed. (Dec 2025), ch. 1, 2, 4 and App. B, G', 'Bryant & O''Hallaron, Computer Systems: A Programmer''s Perspective, 3rd ed., ch. 1, 5, 6 (§1.9.1, §5.7–5.9, §5.14, §6.6)', 'MIT 6.172 Performance Engineering of Software Systems (OCW, Fall 2018)', 'MIT 6.5930 reading list (Spring 2026): Kernel Computation lectures (CPU, Vectorization, Memory)']::text[], '[{"title":"How to Optimize GEMM: step-by-step tutorial","url":"https://github.com/flame/how-to-optimize-gemm/wiki"},{"title":"BLIS framework (study its micro-kernels)","url":"https://github.com/flame/blis"},{"title":"CMSIS-NN int8 kernels for Cortex-M","url":"https://github.com/ARM-software/CMSIS-NN"},{"title":"MIT 6.172 Performance Engineering (OCW) projects","url":"https://ocw.mit.edu/courses/6-172-performance-engineering-of-software-systems-fall-2018/"}]'::jsonb),
  ('embedded-ai/gpus-parallel-programming', 'embedded-ai', 6, 52, 'GPUs and parallel programming', 'You will be able to write and tune GPU kernels in CUDA and Triton by reasoning about warps, memory access patterns, occupancy and tensor cores.', 80, array['Hwu, Kirk & El Hajj, Programming Massively Parallel Processors, 4th ed. (2022), ch. 1–6, 10–11, 16, 20', 'NVIDIA CUDA Programming Guide and CUDA C++ Best Practices Guide (docs.nvidia.com/cuda)', 'Hennessy, Patterson & Kozyrakis, CA:AQA 7e, ch. 4 (GPUs)', 'Tillet, Kung & Cox, Triton, MAPL 2019']::text[], '[{"title":"Triton tutorials: vector add, fused softmax, matrix multiplication","url":"https://triton-lang.org/main/getting-started/tutorials/index.html"},{"title":"How to optimize a CUDA matmul kernel, step by step","url":"https://siboehm.com/articles/22/CUDA-MMM"},{"title":"CUDA Programming Guide","url":"https://docs.nvidia.com/cuda/cuda-programming-guide/"},{"title":"GPU MODE lecture series","url":"https://github.com/gpu-mode/lectures"}]'::jsonb),
  ('embedded-ai/framework-internals', 'embedded-ai', 6, 53, 'Framework internals', 'You will be able to explain what a PyTorch-style framework does between a line of model code and a running kernel, and how trained models are saved for deployment.', 55, array['CMU 10-414/714 Deep Learning Systems (dlsyscourse.org), lectures 4–5, 7, 9, 12–13, 23', 'Janapa Reddi et al., Machine Learning Systems (mlsysbook.ai) Vol. I, ch. 7 (ML Frameworks)', 'Ansel et al., PyTorch 2, ASPLOS 2024']::text[], '[{"title":"CMU Deep Learning Systems assignments: build the needle framework","url":"https://dlsyscourse.org/assignments/"},{"title":"MiniTorch: build a tensor library with autodiff","url":"https://minitorch.github.io/"},{"title":"micrograd: a tiny autograd engine","url":"https://github.com/karpathy/micrograd"}]'::jsonb),
  ('embedded-ai/ml-compilers', 'embedded-ai', 6, 54, 'ML compilers', 'You will be able to explain how ML compilers turn a model graph into fast code for a specific device, and use TVM, MLIR-based tools, XLA, IREE and ExecuTorch.', 110, array['Chen et al., Machine Learning Compilation course notes (mlc.ai, 2022), ch. 1–7', 'Chen et al., TVM: An Automated End-to-End Optimizing Compiler for Deep Learning, OSDI 2018', 'Lattner et al., MLIR: Scaling Compiler Infrastructure for Domain Specific Computation, CGO 2021', 'Ragan-Kelley et al., Halide, PLDI 2013', 'Zheng et al., Ansor, OSDI 2020', 'Stanford CS217 (Winter 2026), Compilers and software stack lectures (parts 1–2)']::text[], '[{"title":"MLC course (2022): episodes, notebooks and exercises","url":"https://mlc.ai/summer22/schedule"},{"title":"Apache TVM documentation (Relax, TensorIR, MetaSchedule)","url":"https://tvm.apache.org/docs/"},{"title":"Halide tutorials","url":"https://halide-lang.org/"},{"title":"IREE: MLIR-based compiler and runtime","url":"https://iree.org/"}]'::jsonb),
  ('embedded-ai/memory-planning', 'embedded-ai', 6, 55, 'Memory planning', 'You will be able to fit a model''s working memory into a small RAM by planning when each tensor lives, where it is stored and how data streams in.', 45, array['MIT 6.5940 TinyML and Efficient Deep Learning Computing (Fall 2024 and Fall 2026), L10 MCUNet and L11 TinyEngine and Parallel Processing', 'Lin et al., MCUNetV2: Memory-Efficient Patch-based Inference for Tiny Deep Learning, NeurIPS 2021', 'Lin et al., MCUNet: Tiny Deep Learning on IoT Devices, NeurIPS 2020']::text[], '[{"title":"TinyEngine (MCUNet inference engine) source","url":"https://github.com/mit-han-lab/tinyengine"},{"title":"ExecuTorch memory planning documentation","url":"https://docs.pytorch.org/executorch/stable/compiler-memory-planning.html"},{"title":"TensorFlow Lite Micro (study the arena planner)","url":"https://github.com/tensorflow/tflite-micro"}]'::jsonb),
  ('embedded-ai/accelerator-fundamentals', 'embedded-ai', 6, 56, 'Accelerator fundamentals', 'You will be able to explain why custom ML chips beat general-purpose processors and how their compute arrays, on-chip memories and interconnects are built.', 85, array['Sze, Chen, Yang & Emer, Efficient Processing of Deep Neural Networks (2020), ch. 1, 3, 5 and 7', 'Jouppi et al., In-Datacenter Performance Analysis of a Tensor Processing Unit, ISCA 2017', 'Hennessy, Patterson & Kozyrakis, CA:AQA 7e, ch. 7 (Domain-Specific Architectures)', 'Stanford CS217 Hardware Accelerators for Machine Learning (Winter 2026): systolic arrays, vector and scalar units, memory systems, interconnects', 'MIT 6.5930/1 Hardware Architecture for Deep Learning (Spring 2026 reading list): Accelerator Architecture']::text[], '[{"title":"SCALE-Sim v3 systolic-array simulator","url":"https://github.com/scalesim-project/scale-sim-v3"},{"title":"Gemmini systolic-array generator","url":"https://github.com/ucb-bar/gemmini"}]'::jsonb),
  ('embedded-ai/dataflow-mapping', 'embedded-ai', 6, 57, 'Dataflow and mapping', 'You will be able to describe any layer as a loop nest, reason about how a chip reuses data, and search for the schedule that minimizes energy and time, using Timeloop.', 100, array['Sze et al., ch. 2, 5 and 6', 'MIT 6.5930/1 Hardware Architecture for Deep Learning (Spring 2026), L03–L07, L13 and recitations (AccelForge tutorial, looptree)', 'Parashar et al., Timeloop: A Systematic Approach to DNN Accelerator Evaluation, ISPASS 2019', 'Wu, Emer & Sze, Accelergy, ICCAD 2019', 'Kwon et al., MAESTRO, MICRO 2019']::text[], '[{"title":"Capstone, step 1a: compile a model with Apache TVM","url":"https://tvm.apache.org/docs/"},{"title":"Capstone, step 1b (alternative): export and lower the model with ExecuTorch","url":"https://docs.pytorch.org/executorch/stable/getting-started.html"},{"title":"Capstone, step 2: map one of its conv layers in Timeloop (exercises)","url":"https://github.com/Accelergy-Project/timeloop-accelergy-exercises"},{"title":"AccelForge (Timeloop successor) documentation","url":"https://accelergy-project.github.io/accelforge/"}]'::jsonb),
  ('embedded-ai/edge-npus', 'embedded-ai', 6, 58, 'Edge NPUs and SoCs', 'You will be able to compare the neural accelerators in microcontrollers and phones, prepare a model for one, and tell advertised TOPS from real performance.', 75, array['Arm Newsroom, Arm Ethos-U85 (9 Apr 2024); Arm Ethos-U55 and Ethos-U65 product pages (arm.com)', 'STMicroelectronics press release P4665, STM32N6 (10 Dec 2024)', 'Janapa Reddi et al., mlsysbook.ai Vol. I, ch. 11 (Hardware Acceleration)', 'Sze et al., ch. 3']::text[], '[{"title":"Arm Ethos-U Vela compiler","url":"https://pypi.org/project/ethos-u-vela/"},{"title":"ExecuTorch Arm Ethos-U backend","url":"https://docs.pytorch.org/executorch/stable/backends-arm-ethos-u.html"},{"title":"ST Edge AI Developer Cloud: benchmark on real STM32 boards","url":"https://stedgeai-dc.st.com/"},{"title":"Qualcomm AI Hub: profile on Snapdragon devices","url":"https://aihub.qualcomm.com/"}]'::jsonb),
  ('embedded-ai/fpga-acceleration', 'embedded-ai', 6, 59, 'FPGA acceleration', 'You will be able to build ML accelerators on FPGAs with high-level synthesis and choose between streaming designs, overlays and existing tools such as FINN, hls4ml and Vitis AI.', 65, array['Kastner, Matai & Neuendorffer, Parallel Programming for FPGAs (arXiv:1805.03648), ch. 1, 2, 7 and 12', 'AMD Vitis HLS User Guide (UG1399)', 'Umuroglu et al., FINN: A Framework for Fast, Scalable Binarized Neural Network Inference, FPGA 2017', 'Duarte et al., Fast inference of deep neural networks in FPGAs for particle physics (hls4ml), JINST 13, P07027, 2018', 'Stanford CS217 (Winter 2026): HLS lectures and labs on cloud FPGAs']::text[], '[{"title":"Parallel Programming for FPGAs: book source and examples","url":"https://github.com/KastnerRG/pp4fpgas"},{"title":"Vitis HLS introductory examples","url":"https://github.com/Xilinx/Vitis-HLS-Introductory-Examples"},{"title":"FINN dataflow compiler","url":"https://github.com/Xilinx/finn"},{"title":"hls4ml","url":"https://github.com/fastmachinelearning/hls4ml"}]'::jsonb),
  ('embedded-ai/deployment-co-optimization', 'embedded-ai', 6, 60, 'Deployment co-optimization', 'You will be able to split a model across a device''s processors, make its integer arithmetic match the hardware exactly, and predict latency before you deploy.', 50, array['Janapa Reddi et al., mlsysbook.ai Vol. I, ch. 10 (Model Compression), ch. 11 (Hardware Acceleration), ch. 12 (Benchmarking)', 'Stanford CS217 Hardware Accelerators for Machine Learning (Winter 2026): compilers and software stack, HW1 and HW3', 'TOSA specification v1.1.0 (arm.github.io/tosa-specification)', 'ExecuTorch documentation: backend delegation and partitioners']::text[], '[{"title":"nn-Meter latency predictor","url":"https://github.com/microsoft/nn-Meter"},{"title":"Qualcomm AI Hub: per-layer profiling on devices","url":"https://aihub.qualcomm.com/"}]'::jsonb),
  ('embedded-ai/graduate-architecture', 'embedded-ai', 7, 61, 'Graduate architecture', 'You will be able to answer qualifying-exam questions on how modern processors execute instructions out of order, predict branches, keep caches coherent, order memory operations and use DRAM.', 90, array['Hennessy, Patterson & Kozyrakis, Computer Architecture: A Quantitative Approach, 7th ed. (Dec 2025), ch. 1–5 and App. B, C', 'Nagarajan, Sorin, Hill & Wood, A Primer on Memory Consistency and Cache Coherence, 2nd ed. (2020)', 'University of Wisconsin–Madison Computer Architecture PhD qualifying exam, Fall 2020 (six questions)', 'Georgia Tech PhD CS computer architecture body of knowledge: CS 6290 and CS 7290 (advanced microarchitecture)']::text[], '[{"title":"Learning gem5 tutorial","url":"https://www.gem5.org/documentation/learning_gem5/introduction/"},{"title":"ChampSim: branch-predictor and prefetcher studies","url":"https://github.com/ChampSim/ChampSim"}]'::jsonb),
  ('embedded-ai/sparse-accelerators', 'embedded-ai', 7, 62, 'Sparse accelerators', 'You will be able to design and evaluate hardware that skips work on zeros, from compressed formats to load balancing, and model it with Sparseloop.', 60, array['Sze et al., §8.1–8.3', 'MIT 6.5930/1 (Spring 2026), L07 Sparsity and L08–L10 Sparse Architectures 1–3', 'Wu et al., Sparseloop: An Analytical Approach to Sparse Tensor Accelerator Modeling, MICRO 2022']::text[], '[{"title":"Timeloop and Sparseloop source","url":"https://github.com/Accelergy-Project/timeloop"}]'::jsonb),
  ('embedded-ai/numerics-co-design', 'embedded-ai', 7, 63, 'Numerics co-design', 'You will be able to choose and justify number formats for ML hardware, from block floating point to OCP MX and NVFP4, including how accumulators, rounding and outliers affect accuracy.', 60, array['Sze et al., ch. 7', 'OCP Microscaling Formats (MX) Specification v1.0 (Sep 2023), §5–6', 'Rouhani et al., Microscaling Data Formats for Deep Learning, arXiv:2310.10537, 2023', 'MIT 6.5930 (Spring 2026), L12 Numeric Precision', 'Stanford CS217 (Winter 2026), Quantization lecture and HW2 (MXFP prologue vs epilogue cost)']::text[], '[{"title":"microxcaling: MX format emulation library (PyTorch)","url":"https://github.com/microsoft/microxcaling"}]'::jsonb),
  ('embedded-ai/hw-algorithm-co-design', 'embedded-ai', 7, 64, 'Hardware/algorithm co-design', 'You will be able to search jointly over model and hardware designs, use fast cost models to guide the search, and present results as honest trade-off curves.', 55, array['Sze et al., ch. 3 and ch. 9', 'Harvard CS249r / Janapa Reddi et al., mlsysbook.ai Vol. I, ch. 10 and 12; Vol. II, ch. 5 and 6', 'Georgia Tech ECE/CS 8803 HML, Hardware Software Co-Design for Machine Learning Systems (Spring 2025): Labs 2–5', 'Lin et al., MCUNet, NeurIPS 2020']::text[], '[{"title":"Once-for-All: hardware-aware NAS","url":"https://github.com/mit-han-lab/once-for-all"},{"title":"ASTRA-sim distributed ML system simulator","url":"https://astra-sim.github.io/"},{"title":"SCALE-Sim v3 for accelerator design-space sweeps","url":"https://github.com/scalesim-project/scale-sim-v3"}]'::jsonb),
  ('embedded-ai/on-device-training', 'embedded-ai', 7, 65, 'On-device training', 'You will be able to make a model keep learning on the device itself by cutting the memory cost of training, from bias-only updates to training in 256 KB and federated learning.', 70, array['MIT 6.5940 TinyML and Efficient Deep Learning Computing (Fall 2024), L21 On-Device Training and Transfer Learning', 'Zhu et al., PockEngine: Sparse and Efficient Fine-tuning in a Pocket, MICRO 2023', 'Lin et al., On-Device Training Under 256KB Memory, NeurIPS 2022', 'Cai et al., TinyTL, NeurIPS 2020', 'Janapa Reddi et al., mlsysbook.ai Vol. II, ch. 11 (Edge Intelligence)']::text[], '[{"title":"tiny-training: on-device training under 256 KB","url":"https://github.com/mit-han-lab/tiny-training"},{"title":"Flower federated learning framework","url":"https://flower.ai/"}]'::jsonb),
  ('embedded-ai/emerging-technologies', 'embedded-ai', 7, 66, 'Emerging technologies', 'You will be able to judge new kinds of ML hardware (analog and in-memory compute, neuromorphic chips, chiplets, approximate computing) by their real system-level gains.', 50, array['Sze et al., ch. 10', 'MIT 6.5930 (Spring 2026), L11 Advanced Technologies', 'Stanford CS217 (Winter 2026), Memory-centric computing lectures (parts 1–2)']::text[], '[{"title":"DNN+NeuroSim compute-in-memory simulator","url":"https://github.com/neurosim/DNN_NeuroSim_V1.4"},{"title":"Lava neuromorphic computing framework","url":"https://github.com/lava-nc/lava"}]'::jsonb),
  ('embedded-ai/trustworthy-embedded-ai', 'embedded-ai', 7, 67, 'Trustworthy embedded AI', 'You will be able to analyse how an embedded ML system can be attacked or fail, protect it with hardware and software measures, and account for its privacy and carbon costs.', 50, array['Janapa Reddi et al., mlsysbook.ai Vol. II, ch. 13 (Security & Privacy), ch. 14 (Robust AI), ch. 15 (Sustainable AI), ch. 16 (Responsible AI)', 'Georgia Tech CS 7292 Reliability and Security in Computer Architecture (body-of-knowledge elective)']::text[], '[{"title":"Adversarial Robustness Toolbox","url":"https://github.com/Trusted-AI/adversarial-robustness-toolbox"},{"title":"CodeCarbon: measure the emissions of ML workloads","url":"https://codecarbon.io/"}]'::jsonb),
  ('embedded-ai/modeling-evaluation', 'embedded-ai', 7, 68, 'Modeling and evaluation', 'You will be able to choose the right simulator or model for a hardware question, run gem5 and Chipyard/Gemmini, estimate power, and report results with statistical care.', 40, array['Berkeley EE 290-2 Hardware for Machine Learning (Shao; Spring 2020–2024 offerings; FireSim-based labs)', 'Genc et al., Gemmini, DAC 2021', 'Amid et al., Chipyard: Integrated Design, Simulation, and Implementation Framework for Custom SoCs, IEEE Micro 40(4), 2020', 'Lowe-Power et al., The gem5 Simulator: Version 20.0+, arXiv:2007.03152, 2020']::text[], '[{"title":"Chipyard documentation","url":"https://chipyard.readthedocs.io/"},{"title":"Gemmini","url":"https://github.com/ucb-bar/gemmini"},{"title":"FireSim","url":"https://github.com/firesim/firesim"}]'::jsonb),
  ('embedded-ai/research-practice', 'embedded-ai', 7, 69, 'Research practice', 'You will be able to read papers efficiently, know where the field publishes, review a paper, and reproduce a published result.', 25, array['Keshav, How to Read a Paper, ACM SIGCOMM Computer Communication Review 37(3), 2007', 'Systems Research Artifacts guides for authors and evaluators (sysartifacts.github.io)', 'cTuning Artifact Evaluation (ctuning.org/ae)', 'Georgia Tech PhD CS computer architecture oral examination (present an external paper)']::text[], '[{"title":"Reproduce one paper''s result: artifact packaging guide","url":"https://sysartifacts.github.io/packaging-guide.html"},{"title":"Reproduce one paper''s result: artifact evaluator guide","url":"https://sysartifacts.github.io/evaluator-guide.html"},{"title":"cTuning artifact evaluation (MICRO, ASPLOS, MLSys): checklist and badges","url":"https://ctuning.org/ae/"},{"title":"ML Reproducibility Challenge","url":"https://reproml.org/"}]'::jsonb),
  ('embedded-ai/llm-compression', 'embedded-ai', 8, 70, 'LLM compression', 'You will be able to compress large language models to 8, 4 or fewer than 2 bits per weight and explain the trade-offs of each leading method.', 70, array['MIT 6.5940 (Fall 2026) L13 LLM Quantization and Deployment and L14 LLM Post Training; (Fall 2024) L13 Efficient LLM Deployment and L14 LLM Post Training', 'Frantar et al., GPTQ, ICLR 2023', 'Lin et al., AWQ, MLSys 2024', 'Xiao et al., SmoothQuant, ICML 2023', 'Lin et al., QServe, MLSys 2025', 'Ashkboos et al., QuaRot, NeurIPS 2024; Liu et al., SpinQuant, ICLR 2025', 'Ma et al., The Era of 1-bit LLMs (BitNet b1.58), arXiv:2402.17764, 2024']::text[], '[{"title":"AWQ and TinyChat code","url":"https://github.com/mit-han-lab/llm-awq"},{"title":"GPTQ reference implementation","url":"https://github.com/IST-DASLab/gptq"},{"title":"torchao: PyTorch quantization library","url":"https://github.com/pytorch/ao"}]'::jsonb),
  ('embedded-ai/on-device-llm-runtimes', 'embedded-ai', 8, 71, 'On-device LLM runtimes', 'You will be able to explain and tune how LLMs run on phones, laptops and boards: why generation is memory-bound, how runtimes manage the KV cache, and how the main open runtimes differ.', 60, array['MIT 6.5940 (Fall 2026), L13 LLM Quantization and Deployment and L15 Long Context LLM', 'Kwon et al., PagedAttention (vLLM), SOSP 2023', 'Dao et al., FlashAttention, NeurIPS 2022', 'Leviathan, Kalman & Matias, Fast Inference from Transformers via Speculative Decoding, ICML 2023', 'Project documentation: llama.cpp and GGUF, MLC LLM, LiteRT-LM, ExecuTorch, bitnet.cpp', 'Janapa Reddi et al., mlsysbook.ai Vol. II, ch. 10 (Serving at Scale) and Inference Foundations appendix']::text[], '[{"title":"llama.cpp","url":"https://github.com/ggml-org/llama.cpp"},{"title":"ExecuTorch LLM getting started","url":"https://docs.pytorch.org/executorch/stable/llm/getting-started.html"},{"title":"MLC LLM","url":"https://llm.mlc.ai/"},{"title":"LiteRT-LM","url":"https://github.com/google-ai-edge/LiteRT-LM"},{"title":"bitnet.cpp","url":"https://github.com/microsoft/BitNet"}]'::jsonb),
  ('embedded-ai/small-on-device-models', 'embedded-ai', 8, 72, 'Small on-device models', 'You will be able to explain how today''s small language models are built to run on phones, using Llama 3.2, Gemma 3n and Apple''s on-device model as worked examples.', 35, array['Meta AI blog, Llama 3.2 announcement (25 Sep 2024) and quantized Llama 3.2 1B/3B models (24 Oct 2024)', 'Google Developers Blog, Introducing Gemma 3n: The developer guide (26 Jun 2025)', 'Apple, Apple Intelligence Foundation Language Models Tech Report 2025 (arXiv:2507.13575)', 'Devvrit et al., MatFormer: Nested Transformer for Elastic Inference, NeurIPS 2024']::text[], '[{"title":"Google AI Edge Gallery: run Gemma models on a phone","url":"https://github.com/google-ai-edge/gallery"}]'::jsonb),
  ('embedded-ai/formats-new-silicon', 'embedded-ai', 8, 73, 'Formats and new silicon', 'You will be able to explain the newest low-bit number formats and the latest CPU, NPU and microcontroller hardware for on-device AI, and check vendor claims against first principles.', 35, array['OCP Microscaling Formats (MX) Specification v1.0 (Sep 2023)', 'NVIDIA Technical Blog, Introducing NVFP4 for Efficient and Accurate Low-Precision Inference (24 Jun 2025)', 'Arm Newsroom, Lumex CSS announcement (10 Sep 2025) and Arm Ethos-U85 (9 Apr 2024)', 'STMicroelectronics press release P4665, STM32N6 (10 Dec 2024)', 'TOSA specification v1.1.0 (arm.github.io/tosa-specification)']::text[], '[{"title":"KleidiAI micro-kernels","url":"https://github.com/ARM-software/kleidiai"},{"title":"microxcaling: MX format emulation","url":"https://github.com/microsoft/microxcaling"},{"title":"ExecuTorch Arm Ethos-U backend","url":"https://docs.pytorch.org/executorch/stable/backends-arm-ethos-u.html"}]'::jsonb),
  ('embedded-ai/efficient-generative-vision', 'embedded-ai', 8, 74, 'Efficient generative vision', 'You will be able to explain how vision transformers and image generators are made fast enough for devices: cheaper attention, fewer tokens, fewer sampling steps and 4-bit diffusion.', 25, array['MIT 6.5940 (Fall 2026) L16 Vision Transformer and L17–L18 Diffusion Model; (Fall 2024) L16–L18', 'Cai et al., EfficientViT, ICCV 2023', 'Bolya et al., Token Merging: Your ViT But Faster, ICLR 2023', 'Li et al., SVDQuant, ICLR 2025']::text[], '[{"title":"Nunchaku: SVDQuant inference engine","url":"https://github.com/nunchaku-tech/nunchaku"},{"title":"ToMe: token merging","url":"https://github.com/facebookresearch/ToMe"}]'::jsonb),
  ('embedded-ai/benchmarks-open-problems', 'embedded-ai', 8, 75, 'Benchmarks and open problems', 'You will be able to read industry benchmark results for edge AI critically and explain the field''s main open problems as of late 2026.', 25, array['MLCommons MLPerf Inference (Edge) results and announcements: v5.1 (Sep 2025), v6.0 (Apr 2026), v6.1 (Sep 2026)', 'MLCommons MLPerf Tiny benchmark page and v1.3 results (Sep 2025)', 'MLCommons MLPerf Client benchmark page (v2.0)', 'Banbury et al., MLPerf Tiny Benchmark, NeurIPS Datasets and Benchmarks Track 2021', 'Reddi et al., MLPerf Inference Benchmark, ISCA 2020']::text[], '[{"title":"MLPerf Tiny reference implementations","url":"https://github.com/mlcommons/tiny"},{"title":"MLPerf Client","url":"https://github.com/mlcommons/mlperf_client"},{"title":"MLPerf Inference reference implementations","url":"https://github.com/mlcommons/inference"}]'::jsonb)
